function fixtures(fixtureId) { const fixture = state.fixtures.find(item => item.id === fixtureId); if (!fixture) { const years = [...new Set(state.fixtures.map(item => item.fixture_date.slice(0,4)))].sort().reverse(); return `<p class="eyebrow">Society calendar</p><h1>Fixtures & results</h1>${years.map(year => `<section class="section"><h2>${year}</h2>${state.fixtures.filter(item => item.fixture_date.startsWith(year)).map(fixtureRow).join('')}</section>`).join('')}`; } const course = setup(fixture.course_setup_id); const people = (state.fixtureParticipants || []).filter(item => item.fixture_id === fixture.id).map(item => ({ ...item, entry: state.entries.find(score => score.fixture_id === fixture.id && score.player_id === item.player_id) })); const hasScores = people.some(item => item.entry); people.sort((a,b) => { if (hasScores) { const aScore = a.entry?.stableford_points, bScore = b.entry?.stableford_points; if (aScore != null || bScore != null) return (Number(bScore ?? -1) - Number(aScore ?? -1)) || `${a.players?.surname}`.localeCompare(`${b.players?.surname}`); if (a.entry && !b.entry) return -1; if (!a.entry && b.entry) return 1; } return `${a.players?.surname}`.localeCompare(`${b.players?.surname}`) || `${a.players?.first_name}`.localeCompare(`${b.players?.first_name}`); }); const rows = people.map(item => { const index = item.handicap_index_override ?? snapshot(item.player_id)?.index_value; return `<tr><td>${esc(item.players?.first_name)} ${esc(item.players?.surname)}${item.is_guest ? ' (Guest)' : ''}</td><td>${index == null ? '—' : Number(index).toFixed(1)}</td><td>${course && index != null ? playingHandicap(index, fixture, course) : '—'}</td><td>${item.entry ? (item.entry.gross_score == null ? 'NR' : item.entry.gross_score) : '—'}</td><td>${item.entry?.stableford_points ?? '—'}</td></tr>`; }).join(''); return `<p class="eyebrow">${date(fixture.fixture_date)}</p><h1>${esc(fixture.name)}${fixture.competition_name ? ` – ${esc(fixture.competition_name)}` : ''}</h1>${course ? `<p class="intro">Par ${course.par} · Slope ${course.slope_rating} · Course rating ${course.course_rating}</p>` : ''}<section class="section"><table class="table"><thead><tr><th>Player</th><th>Index</th><th>Playing</th><th>Gross</th><th>Pts</th></tr></thead><tbody>${rows}</tbody></table></section>`; }
function memberLabel(member) { return `${esc(member.surname).toUpperCase()}, ${esc(member.first_name)}`; }
