function render() { const [route, detailId] = (location.hash.slice(1) || 'home').split('/'), pages = { home, handicap, fixtures, merit }; app.innerHTML = route === 'fixtures' ? fixtures(detailId) : route === 'admin' ? (detailId === 'members' || !detailId ? membershipAdmin() : detailId === 'participants' ? participantAdmin() : detailId === 'scores' ? scoresAdmin() : admin(detailId)) : (pages[route] || home)(); document.querySelectorAll('.bottom-nav a').forEach(anchor => anchor.classList.toggle('active', anchor.dataset.route === route)); const current = player(); document.querySelector('#initials').textContent = current ? `${current.first_name[0]}${current.surname[0]}`.toUpperCase() : 'EO'; playerButton.hidden = !state.isStaff; adminNav.hidden = !state.isStaff; if (route === 'admin') { bindAdmin(); bindScoreParticipantFilters(); } document.querySelector('#merit-year')?.addEventListener('change', event => { window.electricalOpenMeritYear = event.target.value; render(); }); }

window.addEventListener('hashchange', event => { const previous = new URL(event.oldURL).hash, match = previous.match(/^#admin\/(members|fixtures|participants|course|scores)$/); if (location.hash === '#admin' && match) { history.replaceState(null, '', `#admin/${match[1]}`); render(); } });

function fixtureScorecardDetail(entryId) { const entry = state.entries.find(item => item.id === entryId), fixture = entry && state.fixtures.find(item => item.id === entry.fixture_id), course = fixture && setup(fixture.course_setup_id); if (!entry || !fixture) return `<h1>Scorecard unavailable</h1>${link('fixtures', 'Back to fixtures')}`; setTimeout(() => loadFixtureScorecard(entry, fixture, course), 0); return `<p class="eyebrow">${date(fixture.fixture_date)}</p><h1>${esc(entry.player_name)}</h1><p class="intro">Loading scorecard…</p><p>${link(`fixtures/${fixture.id}`, 'Back to fixture')}</p>`; }

async function loadFixtureScorecard(entry, fixture, course) { const { data: scores, error } = await client.from('hole_scores').select('hole_number, gross_score, handicap_strokes, nett_score, stableford_points').eq('fixture_entry_id', entry.id).order('hole_number'); if (location.hash !== `#scorecard/${entry.id}`) return; if (error || !scores?.length) { app.innerHTML = `<p class="eyebrow">${date(fixture.fixture_date)}</p><h1>${esc(entry.player_name)}</h1>${empty(error ? error.message : 'No hole-by-hole scorecard was saved for this round.')}<p>${link(`fixtures/${fixture.id}`, 'Back to fixture')}</p>`; return; } const courseHoles = holes(course?.id), total = key => scores.reduce((sum, score) => sum + Number(score[key] || 0), 0), rows = scores.map(score => { const hole = courseHoles.find(item => item.hole_number === score.hole_number); return `<tr><td>${score.hole_number}</td><td>${hole?.par ?? '—'}</td><td>${hole?.stroke_index ?? '—'}</td><td>${score.gross_score}</td><td>${score.nett_score}</td><td>${score.stableford_points}</td></tr>`; }).join(''); app.innerHTML = `<p class="eyebrow">${date(fixture.fixture_date)} · ${esc(fixture.name)}</p><h1>${esc(entry.player_name)}</h1><p class="intro">Gross ${entry.gross_score ?? '—'} · Nett ${entry.nett_score ?? '—'} · ${entry.stableford_points ?? '—'} Stableford points</p><section class="section"><div class="table-responsive"><table class="table"><thead><tr><th>Hole</th><th>Par</th><th>SI</th><th>Gross</th><th>Nett</th><th>Pts</th></tr></thead><tbody>${rows}<tr><td><strong>Total</strong></td><td>${course?.par ?? '—'}</td><td></td><td><strong>${total('gross_score')}</strong></td><td><strong>${total('nett_score')}</strong></td><td><strong>${total('stableford_points')}</strong></td></tr></tbody></table></div></section><p>${link(`fixtures/${fixture.id}`, 'Back to fixture')}</p>`; }

function addFixtureScorecardLinks(fixtureId) { const entriesForFixture = state.entries.filter(item => item.fixture_id === fixtureId); document.querySelectorAll('#app tbody tr').forEach(row => { const cells = row.querySelectorAll('td'); if (cells.length < 2) return; const playerCell = cells[1], displayName = playerCell.textContent.replace(/\s*\(Guest\)\s*$/, '').trim(), entry = entriesForFixture.find(item => item.player_name === displayName); if (entry) playerCell.innerHTML = `<a class="text-link" href="#scorecard/${entry.id}">${esc(playerCell.textContent)}</a>`; }); }

function applyFixtureScorecardRoute() { const scorecardMatch = location.hash.match(/^#scorecard\/([^/]+)$/); if (scorecardMatch) { app.innerHTML = fixtureScorecardDetail(scorecardMatch[1]); return; } const fixtureMatch = location.hash.match(/^#fixtures\/([^/]+)$/); if (fixtureMatch) addFixtureScorecardLinks(fixtureMatch[1]); }

window.addEventListener('hashchange', applyFixtureScorecardRoute);

function handicapDifferentialChart(rounds, currentIndex) {
  const points = rounds.filter(item => item.score_differential != null).slice(0, 12).reverse();
  if (!points.length) return '';
  const values = points.map(item => Number(item.score_differential));
  if (currentIndex != null) values.push(Number(currentIndex));
  const minimum = Math.floor(Math.min(...values) - 2);
  const maximum = Math.ceil(Math.max(...values) + 2);
  const range = Math.max(1, maximum - minimum), width = 320, height = 180, left = 32, right = 10, top = 16, bottom = 28;
  const x = position => points.length === 1 ? (left + width - right) / 2 : left + position * ((width - left - right) / (points.length - 1));
  const y = value => top + (maximum - value) * ((height - top - bottom) / range);
  const line = points.map((item, position) => `${x(position).toFixed(1)},${y(Number(item.score_differential)).toFixed(1)}`).join(' ');
  const indexY = currentIndex == null ? null : y(Number(currentIndex));
  const grid = [minimum, (minimum + maximum) / 2, maximum].map(value => `<g><line x1="${left}" x2="${width - right}" y1="${y(value)}" y2="${y(value)}" class="differential-grid"/><text x="${left - 5}" y="${y(value) + 4}" text-anchor="end">${Number(value).toFixed(0)}</text></g>`).join('');
  const dots = points.map((item, position) => `<g><title>${date(item.fixture_date)}: ${Number(item.score_differential).toFixed(1)}</title><circle cx="${x(position)}" cy="${y(Number(item.score_differential))}" r="4.5" class="differential-dot"/></g>`).join('');
  return `<section class="section differential-chart-card"><div class="section-head"><h2>Score differentials</h2><span class="pill">Last ${points.length}</span></div><p class="intro">Each point is a qualifying round. The line marks your current society index.</p><svg class="differential-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Score differentials chart with current handicap index line">${grid}${indexY == null ? '' : `<line x1="${left}" x2="${width - right}" y1="${indexY}" y2="${indexY}" class="current-index-line"/><text x="${width - right}" y="${indexY - 5}" text-anchor="end" class="current-index-label">Index ${Number(currentIndex).toFixed(1)}</text>`}<polyline points="${line}" class="differential-line"/>${dots}</svg><div class="chart-key"><span><i class="chart-key-dot"></i> Differential</span>${indexY == null ? '' : '<span><i class="chart-key-line"></i> Current index</span>'}</div></section>`;
}

function handicap(roundId) { const current = player(); if (!current) return empty('No player is linked to this account yet.'); const recent = entries(current.id); if (roundId) { const entry = recent.find(item => item.id === roundId), fixture = entry && state.fixtures.find(item => item.id === entry.fixture_id), course = fixture && setup(fixture.course_setup_id); if (!entry) return `<h1>Scorecard unavailable</h1>${link('handicap', 'Back to handicap')}`; setTimeout(() => loadHandicapScorecard(entry, course), 0); return `<p class="eyebrow">${date(entry.fixture_date)}</p><h1>${esc(entry.fixture_name)}</h1><p class="intro">Loading scorecard…</p><p>${link('handicap', 'Back to handicap')}</p>`; } const index = snapshot(current.id), club = current.club_handicap, submitted = current.club_handicap_submitted_at ? new Intl.DateTimeFormat('en-GB', { day:'2-digit', month:'short', year:'numeric' }).format(new Date(current.club_handicap_submitted_at)) : 'Not submitted'; return `<p class="eyebrow">${esc(current.first_name)} ${esc(current.surname)}</p><h1>Your handicap</h1><section class="index-card"><p class="eyebrow">Current society index</p><div class="index">${index ? Number(index.index_value).toFixed(1) : '—'}</div><p class="index-note">Club handicap: <strong>${club == null ? '—' : Number(club).toFixed(1)}</strong><br>Submitted: ${submitted}</p></section>${handicapDifferentialChart(recent, index?.index_value)}<section class="section"><div class="section-head"><h2>Latest rounds</h2><span class="pill">Tap a round</span></div>${recent.length ? `<table class="table"><tbody>${recent.slice(0,12).map(item => `<tr data-round-id="${item.id}" style="cursor:pointer"><td><strong>${date(item.fixture_date)}</strong><br><span>${esc(item.fixture_name)}</span></td><td>${item.score_differential == null ? '—' : Number(item.score_differential).toFixed(1)}</td></tr>`).join('')}</tbody></table>` : empty('No qualifying rounds available.')}</section>`; }

async function loadHandicapScorecard(entry, course) { const { data: scores, error } = await client.from('hole_scores').select('hole_number, gross_score, handicap_strokes, nett_score, stableford_points').eq('fixture_entry_id', entry.id).order('hole_number'); if (location.hash !== `#handicap/${entry.id}`) return; if (error || !scores?.length) { app.innerHTML = `<p class="eyebrow">${date(entry.fixture_date)}</p><h1>${esc(entry.fixture_name)}</h1>${empty(error ? error.message : 'No hole-by-hole scorecard was saved for this round.')}<p>${link('handicap', 'Back to handicap')}</p>`; return; } const courseHoles = holes(course?.id), total = key => scores.reduce((sum, score) => sum + Number(score[key] || 0), 0), rows = scores.map(score => { const hole = courseHoles.find(item => item.hole_number === score.hole_number); return `<tr><td>${score.hole_number}</td><td>${hole?.par ?? '—'}</td><td>${hole?.stroke_index ?? '—'}</td><td>${score.gross_score}</td><td>${score.nett_score}</td><td>${score.stableford_points}</td></tr>`; }).join(''); app.innerHTML = `<p class="eyebrow">${date(entry.fixture_date)}</p><h1>${esc(entry.fixture_name)}</h1><p class="intro">Gross ${entry.gross_score ?? '—'} · Nett ${entry.nett_score ?? '—'} · ${entry.stableford_points ?? '—'} Stableford points</p><section class="section"><div class="table-responsive"><table class="table"><thead><tr><th>Hole</th><th>Par</th><th>SI</th><th>Gross</th><th>Nett</th><th>Pts</th></tr></thead><tbody>${rows}<tr><td><strong>Total</strong></td><td>${course?.par ?? '—'}</td><td></td><td><strong>${total('gross_score')}</strong></td><td><strong>${total('nett_score')}</strong></td><td><strong>${total('stableford_points')}</strong></td></tr></tbody></table></div></section><p>${link('handicap', 'Back to handicap')}</p>`; }

function render() { const [route, detailId] = (location.hash.slice(1) || 'home').split('/'), pages = { home, handicap, fixtures, merit }; app.innerHTML = route === 'fixtures' ? fixtures(detailId) : route === 'handicap' ? handicap(detailId) : route === 'scorecard' ? fixtureScorecardDetail(detailId) : route === 'merit' ? merit(detailId) : route === 'admin' ? (detailId === 'members' || !detailId ? membershipAdmin() : detailId === 'participants' ? participantAdmin() : detailId === 'scores' ? scoresAdmin() : admin(detailId)) : (pages[route] || home)(); document.querySelectorAll('.bottom-nav a').forEach(anchor => anchor.classList.toggle('active', anchor.dataset.route === route)); const current = player(); document.querySelector('#initials').textContent = current ? `${current.first_name[0]}${current.surname[0]}`.toUpperCase() : 'EO'; playerButton.hidden = !state.isStaff; adminNav.hidden = !state.isStaff; if (route === 'admin') { bindAdmin(); bindScoreParticipantFilters(); } document.querySelectorAll('[data-round-id]').forEach(row => row.addEventListener('click', () => { location.hash = `#handicap/${row.dataset.roundId}`; })); document.querySelector('#merit-year')?.addEventListener('change', event => { window.electricalOpenMeritYear = event.target.value; render(); }); }

async function saveFixture(event) { event.preventDefault(); const data = new FormData(event.currentTarget), { error } = await client.from('fixtures').insert({ name: data.get('name').trim(), competition_name: data.get('competition_name')?.trim() || null, fixture_date: data.get('fixture_date'), tee_time: data.get('tee_time'), format: data.get('format'), status: 'draft' }); if (error) return message(error.message, true); await load(); location.hash = '#admin/fixtures'; message('Fixture created with an empty participant list. Add players in Fixture Participants.'); }

async function load() { const results = await Promise.all([client.from('user_roles').select('role'), client.from('players').select('id, profile_id, surname, first_name, is_guest, club_handicap, club_handicap_submitted_at').eq('active', true).order('surname'), client.rpc('current_handicap_indexes'), client.from('fixtures').select('id, fixture_date, tee_time, name, competition_name, status, is_historical, course_setup_id, handicap_allowance, playing_conditions_adjustment').order('fixture_date', { ascending: false }), client.from('fixture_entries').select('id, player_id, fixture_id, handicap_index_at_entry, gross_score, nett_score, stableford_points, score_differential, competition_position, order_of_merit_points, players(surname, first_name), fixtures(fixture_date, name)'), client.from('course_setups').select('id, tee_name, course_rating, slope_rating, par, courses(name)').order('tee_name'), client.from('course_holes').select('course_setup_id, hole_number, par, stroke_index').order('hole_number'), client.from('fixture_participants').select('fixture_id, player_id, handicap_index_override, is_guest, players(first_name, surname)'), client.from('hole_scores').select('fixture_entry_id, hole_number, gross_score'), client.from('season_members').select('season_year, player_id')]); const error = results.map(item => item.error).find(Boolean); if (error) throw error; const [roles, directory, snapshots, fixtureData, entryData, courseSetups, courseHoles, participants, holeScores, seasonMembers] = results.map(item => item.data || []); state.isStaff = roles.some(item => ['scorekeeper','handicap_committee','admin'].includes(item.role)); state.memberDirectory = directory; state.players = directory.filter(item => state.isStaff || item.profile_id === session.user.id); state.snapshots = snapshots; state.fixtures = fixtureData; state.courseSetups = courseSetups; state.courseHoles = courseHoles; state.fixtureParticipants = participants; state.holeScores = holeScores; state.seasonMembers = seasonMembers; state.entries = entryData.map(item => ({ ...item, fixture_date: item.fixtures?.fixture_date, fixture_name: item.fixtures?.name, player_name: item.players ? `${item.players.first_name} ${item.players.surname}` : 'Unknown player' })).filter(item => item.fixture_date); const selectedPlayerId = state.players.some(item => item.id === state.selectedPlayerId) ? state.selectedPlayerId : state.players[0]?.id || null; const currentSeason = new Date().getFullYear(); const currentMemberIds = new Set(state.seasonMembers.filter(item => Number(item.season_year) === currentSeason).map(item => item.player_id)); const currentMembers = state.players.filter(item => !item.is_guest && currentMemberIds.has(item.id)); const otherPlayers = state.players.filter(item => !currentMembers.some(member => member.id === item.id)); const playerOptions = players => players.map(item => `<option value="${item.id}"${item.id === selectedPlayerId ? ' selected' : ''}>${esc(item.first_name)} ${esc(item.surname)}${item.is_guest ? ' (Guest)' : ''}</option>`).join(''); state.selectedPlayerId = selectedPlayerId; select.innerHTML = `${currentMembers.length ? `<optgroup label="${currentSeason} members">${playerOptions(currentMembers)}</optgroup>` : ''}${otherPlayers.length ? `<optgroup label="Other players">${playerOptions(otherPlayers)}</optgroup>` : ''}`; nav.hidden = false; signoutButton.hidden = false; render(); }

function fixtures(fixtureId) { const fixture = state.fixtures.find(item => item.id === fixtureId); if (!fixture) { const years = [...new Set(state.fixtures.map(item => item.fixture_date.slice(0,4)))].sort().reverse(); return `<p class="eyebrow">Society calendar</p><h1>Fixtures & results</h1>${years.map(year => `<section class="section"><h2>${year}</h2>${state.fixtures.filter(item => item.fixture_date.startsWith(year)).map(fixtureRow).join('')}</section>`).join('')}`; } const course = setup(fixture.course_setup_id), people = (state.fixtureParticipants || []).filter(item => item.fixture_id === fixture.id).map(item => ({ ...item, entry: state.entries.find(score => score.fixture_id === fixture.id && score.player_id === item.player_id) })), hasScores = people.some(item => item.entry); people.sort((a, b) => { const aPosition = a.entry?.competition_position, bPosition = b.entry?.competition_position; if (aPosition != null || bPosition != null) return (aPosition ?? Number.MAX_SAFE_INTEGER) - (bPosition ?? Number.MAX_SAFE_INTEGER) || `${a.players?.surname}`.localeCompare(`${b.players?.surname}`); if (hasScores) { const aPoints = a.entry?.stableford_points, bPoints = b.entry?.stableford_points; if (aPoints != null || bPoints != null) return Number(bPoints ?? -1) - Number(aPoints ?? -1) || `${a.players?.surname}`.localeCompare(`${b.players?.surname}`); } return `${a.players?.surname}`.localeCompare(`${b.players?.surname}`) || `${a.players?.first_name}`.localeCompare(`${b.players?.first_name}`); }); const rows = people.map(item => { const index = item.handicap_index_override ?? snapshot(item.player_id)?.index_value, entry = item.entry; return `<tr><td>${entry?.competition_position ?? '—'}</td><td>${esc(item.players?.first_name)} ${esc(item.players?.surname)}${item.is_guest ? ' (Guest)' : ''}</td><td>${index == null ? '—' : Number(index).toFixed(1)}</td><td>${course && index != null ? playingHandicap(index, fixture, course) : '—'}</td><td>${entry ? (entry.gross_score == null ? 'NR' : entry.gross_score) : '—'}</td><td>${entry?.nett_score ?? '—'}</td><td>${entry?.stableford_points ?? '—'}</td><td>${entry?.order_of_merit_points ?? '—'}</td></tr>`; }).join(''); return `<p class="eyebrow">${date(fixture.fixture_date)}</p><h1>${esc(fixture.name)}${fixture.competition_name ? ` – ${esc(fixture.competition_name)}` : ''}</h1>${course ? `<p class="intro">Par ${course.par} · Slope ${course.slope_rating} · Course rating ${course.course_rating}</p>` : ''}<section class="section"><div class="table-responsive"><table class="table"><thead><tr><th>Pos</th><th>Player</th><th>Index</th><th>Playing</th><th>Gross</th><th>Nett</th><th>Pts</th><th>OOM</th></tr></thead><tbody>${rows || '<tr><td colspan="8">No participants added.</td></tr>'}</tbody></table></div>${hasScores && people.some(item => item.entry?.competition_position == null) ? '<p class="intro">Finalise results to apply the countback and Order of Merit positions.</p>' : ''}</section>`; }

// A display-only legacy value can appear in history without becoming a qualifying round.
const loadWithQualifyingDifferentials = load;
function displayedDifferential(entry) { return entry.score_differential ?? entry.historic_display_differential; }
load = async function() {
  await loadWithQualifyingDifferentials();
  const { data, error } = await client.from('fixture_entries').select('id, historic_display_differential').not('historic_display_differential', 'is', null);
  if (error) throw error;
  const displayValues = new Map((data || []).map(item => [item.id, item.historic_display_differential]));
  state.entries.forEach(entry => { entry.historic_display_differential = displayValues.get(entry.id) ?? null; });
  render();
};

const qualifyingDifferentialChart = handicapDifferentialChart;
function handicap(roundId) {
  const current = player();
  if (!current) return empty('No player is linked to this account yet.');
  const recent = entries(current.id);
  if (roundId) {
    const entry = recent.find(item => item.id === roundId), fixture = entry && state.fixtures.find(item => item.id === entry.fixture_id), course = fixture && setup(fixture.course_setup_id);
    if (!entry) return `<h1>Scorecard unavailable</h1>${link('handicap', 'Back to handicap')}`;
    setTimeout(() => loadHandicapScorecard(entry, course), 0);
    return `<p class="eyebrow">${date(entry.fixture_date)}</p><h1>${esc(entry.fixture_name)}</h1><p class="intro">Loading scorecard…</p><p>${link('handicap', 'Back to handicap')}</p>`;
  }
  const index = snapshot(current.id), club = current.club_handicap;
  const submitted = current.club_handicap_submitted_at ? new Intl.DateTimeFormat('en-GB', { day:'2-digit', month:'short', year:'numeric' }).format(new Date(current.club_handicap_submitted_at)) : 'Not submitted';
  const chartRounds = recent.map(item => ({ ...item, score_differential: displayedDifferential(item) }));
  const hasDisplayOnly = recent.some(item => item.score_differential == null && item.historic_display_differential != null);
  return `<p class="eyebrow">${esc(current.first_name)} ${esc(current.surname)}</p><h1>Your handicap</h1><section class="index-card"><p class="eyebrow">Current society index</p><div class="index">${index ? Number(index.index_value).toFixed(1) : '—'}</div><p class="index-note">Club handicap: <strong>${club == null ? '—' : Number(club).toFixed(1)}</strong><br>Submitted: ${submitted}</p></section>${qualifyingDifferentialChart(chartRounds, index?.index_value)}${hasDisplayOnly ? '<p class="intro">Historic display-only differentials are shown for reference and do not affect your current index.</p>' : ''}<section class="section"><div class="section-head"><h2>Latest rounds</h2><span class="pill">Tap a round</span></div>${recent.length ? `<table class="table"><tbody>${recent.slice(0,12).map(item => { const differential = displayedDifferential(item); return `<tr data-round-id="${item.id}" style="cursor:pointer"><td><strong>${date(item.fixture_date)}</strong><br><span>${esc(item.fixture_name)}${item.score_differential == null && differential != null ? ' · historic' : ''}</span></td><td>${differential == null ? '—' : Number(differential).toFixed(1)}</td></tr>`; }).join('')}</tbody></table>` : empty('No rounds available.')}</section>`;
}
